from datetime import datetime, timedelta, timezone
from functools import wraps
from typing import Optional

from fastapi import FastAPI, HTTPException, Header, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from jose import JWTError, jwt
from passlib.context import CryptContext
from pydantic import BaseModel
from sqlalchemy import Column, DateTime, ForeignKey, Integer, String, create_engine, desc, func
from sqlalchemy.orm import declarative_base, relationship, sessionmaker, Session


DATABASE_URL = "sqlite:///./app.db"
SECRET_KEY = "change-me-please"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 60 * 24

engine = create_engine(DATABASE_URL, connect_args={"check_same_thread": False})
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()
pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
bearer_scheme = HTTPBearer(auto_error=False)

app = FastAPI(title="Zadania API")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True, index=True)
    username = Column(String, unique=True, index=True, nullable=False)
    password_hash = Column(String, nullable=False)
    is_admin = Column(Integer, default=0, nullable=False)
    points = Column(Integer, default=0, nullable=False)
    submissions = relationship("Submission", back_populates="user", cascade="all, delete-orphan")


class Task(Base):
    __tablename__ = "tasks"
    id = Column(Integer, primary_key=True, index=True)
    prompt = Column(String, nullable=False)
    correct_answer = Column(String, nullable=False)
    points = Column(Integer, nullable=False)
    submissions = relationship("Submission", back_populates="task", cascade="all, delete-orphan")


class Submission(Base):
    __tablename__ = "submissions"
    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=False)
    task_id = Column(Integer, ForeignKey("tasks.id"), nullable=False)
    answer = Column(String, nullable=False)
    is_correct = Column(Integer, nullable=False)
    points_awarded = Column(Integer, nullable=False)
    submitted_at = Column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)
    user = relationship("User", back_populates="submissions")
    task = relationship("Task", back_populates="submissions")


class RegisterRequest(BaseModel):
    username: str
    password: str


class LoginRequest(BaseModel):
    username: str
    password: str


class SubmitRequest(BaseModel):
    task_id: int
    answer: str


class TokenResponse(BaseModel):
    token: str


class RankingItem(BaseModel):
    username: str
    points: int


class TaskOut(BaseModel):
    id: int
    prompt: str
    points: int

    class Config:
        from_attributes = True


class SubmissionOut(BaseModel):
    id: int
    user_id: int
    task_id: int
    answer: str
    is_correct: bool
    points_awarded: int
    submitted_at: datetime

    class Config:
        from_attributes = True


class UserOut(BaseModel):
    id: int
    username: str
    points: int
    is_admin: bool

    class Config:
        from_attributes = True


class DeleteResponse(BaseModel):
    detail: str


def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def hash_password(password: str) -> str:
    return pwd_context.hash(password)


def verify_password(password: str, password_hash: str) -> bool:
    return pwd_context.verify(password, password_hash)


def create_access_token(data: dict) -> str:
    to_encode = data.copy()
    expire = datetime.now(timezone.utc) + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    to_encode.update({"exp": expire})
    return jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)


def normalize_answer(value: str) -> str:
    return value.strip().lower()


def init_db():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        admin = db.query(User).filter(User.username == "admin").first()
        if not admin:
            admin = User(
                username="admin",
                password_hash=hash_password("admin123"),
                is_admin=1,
                points=0,
            )
            db.add(admin)
        tasks = [
            ("Ile to 2 + 2?", "4", 1),
            ("Stolica Polski?", "Warszawa", 2),
            ("Rok bitwy pod Grunwaldem?", "1410", 3),
        ]
        for prompt, answer, points in tasks:
            exists = db.query(Task).filter(Task.prompt == prompt).first()
            if not exists:
                db.add(Task(prompt=prompt, correct_answer=normalize_answer(answer), points=points))
        db.commit()
    finally:
        db.close()


@app.on_event("startup")
def startup_event():
    init_db()


def get_current_user(authorization: Optional[HTTPAuthorizationCredentials] = None, db: Session = None) -> User:
    if db is None:
        raise HTTPException(status_code=500, detail="Database session missing")
    if authorization is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    token = authorization.credentials
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: Optional[str] = payload.get("sub")
        if not username:
            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    except JWTError:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    user = db.query(User).filter(User.username == username).first()
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return user


@app.post("/register")
def register(payload: RegisterRequest, db: Session = next(get_db())):
    if db.query(User).filter(User.username == payload.username).first():
        raise HTTPException(status_code=400, detail="Username already exists")
    user = User(username=payload.username, password_hash=hash_password(payload.password), is_admin=0, points=0)
    db.add(user)
    db.commit()
    db.refresh(user)
    return {"id": user.id, "username": user.username}


@app.post("/login", response_model=TokenResponse)
def login(payload: LoginRequest, db: Session = next(get_db())):
    user = db.query(User).filter(User.username == payload.username).first()
    if not user or not verify_password(payload.password, user.password_hash):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = create_access_token({"sub": user.username, "is_admin": bool(user.is_admin)})
    return TokenResponse(token=token)


@app.get("/tasks", response_model=list[TaskOut])
def list_tasks(db: Session = next(get_db()), authorization: Optional[HTTPAuthorizationCredentials] = None):
    user = get_current_user(authorization, db)
    _ = user
    return db.query(Task).order_by(Task.id.asc()).all()


@app.post("/submit")
def submit(payload: SubmitRequest, db: Session = next(get_db()), authorization: Optional[HTTPAuthorizationCredentials] = None):
    user = get_current_user(authorization, db)
    task = db.query(Task).filter(Task.id == payload.task_id).first()
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    correct = normalize_answer(payload.answer) == task.correct_answer
    points_awarded = task.points if correct else 0
    submission = Submission(
        user_id=user.id,
        task_id=task.id,
        answer=payload.answer,
        is_correct=1 if correct else 0,
        points_awarded=points_awarded,
    )
    db.add(submission)
    if correct:
        user.points += task.points
    db.commit()
    db.refresh(submission)
    return {"id": submission.id, "correct": correct, "points_awarded": points_awarded}


@app.get("/submissions/{submission_id}", response_model=SubmissionOut)
def get_submission(submission_id: int, db: Session = next(get_db()), authorization: Optional[HTTPAuthorizationCredentials] = None):
    user = get_current_user(authorization, db)
    submission = db.query(Submission).filter(Submission.id == submission_id).first()
    if not submission:
        raise HTTPException(status_code=404, detail="Submission not found")
    if submission.user_id != user.id and not user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden")
    return submission


@app.get("/ranking", response_model=list[RankingItem])
def ranking(db: Session = next(get_db()), authorization: Optional[HTTPAuthorizationCredentials] = None):
    user = get_current_user(authorization, db)
    _ = user
    results = db.query(User.username, User.points).order_by(desc(User.points), User.username.asc()).all()
    return [RankingItem(username=username, points=points) for username, points in results]


@app.delete("/users/{user_id}", response_model=DeleteResponse)
def delete_user(user_id: int, db: Session = next(get_db()), authorization: Optional[HTTPAuthorizationCredentials] = None):
    user = get_current_user(authorization, db)
    if not user.is_admin:
        raise HTTPException(status_code=403, detail="Admin only")
    if user.id == user_id:
        raise HTTPException(status_code=400, detail="Admin cannot delete itself")
    target = db.query(User).filter(User.id == user_id).first()
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    db.delete(target)
    db.commit()
    return DeleteResponse(detail="User deleted")

