from __future__ import annotations

import os
import sqlite3
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List

import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

APP_DB = os.getenv("APP_DB", "app.db")
JWT_SECRET = os.getenv("JWT_SECRET", "change-me-in-production-please-use-longer-secret")
JWT_ALGORITHM = "HS256"
JWT_EXPIRY_MINUTES = 60 * 24

app = FastAPI(title="Zadania API")
security = HTTPBearer(auto_error=False)


class RegisterRequest(BaseModel):
    username: str = Field(min_length=3, max_length=64)
    password: str = Field(min_length=6, max_length=128)


class LoginRequest(BaseModel):
    username: str = Field(min_length=3, max_length=64)
    password: str = Field(min_length=6, max_length=128)


class SubmitRequest(BaseModel):
    task_id: int
    answer: str = Field(min_length=1, max_length=256)


class TokenResponse(BaseModel):
    token: str


class TaskOut(BaseModel):
    id: int
    title: str
    points: int


class SubmissionOut(BaseModel):
    id: int
    user_id: int
    task_id: int
    answer: str
    is_correct: bool
    points_awarded: int
    created_at: str


class RankingRow(BaseModel):
    username: str
    points: int


def get_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(APP_DB)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db() -> None:
    with get_conn() as conn:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                password TEXT NOT NULL,
                is_admin INTEGER NOT NULL DEFAULT 0,
                points INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                answer TEXT NOT NULL,
                points INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                task_id INTEGER NOT NULL,
                answer TEXT NOT NULL,
                is_correct INTEGER NOT NULL,
                points_awarded INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE
            );
            """
        )
        if conn.execute("SELECT 1 FROM users WHERE username = ?", ("admin",)).fetchone() is None:
            conn.execute("INSERT INTO users (username, password, is_admin, points) VALUES (?, ?, 1, 0)", ("admin", "admin123"))
        if conn.execute("SELECT COUNT(*) AS c FROM tasks").fetchone()["c"] == 0:
            conn.executemany(
                "INSERT INTO tasks (title, answer, points) VALUES (?, ?, ?)",
                [("Ile to 2 + 2?", "4", 1), ("Stolica Polski?", "Warszawa", 2), ("Rok bitwy pod Grunwaldem?", "1410", 3)],
            )


@app.on_event("startup")
def on_startup() -> None:
    init_db()


def create_token(user: sqlite3.Row) -> str:
    exp = datetime.now(timezone.utc) + timedelta(minutes=JWT_EXPIRY_MINUTES)
    payload = {"sub": str(user["id"]), "username": user["username"], "is_admin": bool(user["is_admin"]), "exp": exp}
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)


def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)) -> sqlite3.Row:
    if credentials is None or credentials.scheme.lower() != "bearer":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    try:
        claims = jwt.decode(credentials.credentials, JWT_SECRET, algorithms=[JWT_ALGORITHM])
    except Exception:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    with get_conn() as conn:
        user = conn.execute("SELECT * FROM users WHERE id = ?", (int(claims["sub"]),)).fetchone()
    if user is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return user


def require_admin(user: sqlite3.Row = Depends(get_current_user)) -> sqlite3.Row:
    if not user["is_admin"]:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Admin only")
    return user


@app.post("/register", status_code=201)
def register(payload: RegisterRequest) -> Dict[str, Any]:
    init_db()
    with get_conn() as conn:
        try:
            conn.execute("INSERT INTO users (username, password, is_admin, points) VALUES (?, ?, 0, 0)", (payload.username, payload.password))
        except sqlite3.IntegrityError:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Username already exists")
    return {"message": "registered"}


@app.post("/login", response_model=TokenResponse)
def login(payload: LoginRequest) -> TokenResponse:
    init_db()
    with get_conn() as conn:
        user = conn.execute("SELECT * FROM users WHERE username = ? AND password = ?", (payload.username, payload.password)).fetchone()
    if user is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    return TokenResponse(token=create_token(user))


@app.get("/tasks", response_model=List[TaskOut])
def tasks(_: sqlite3.Row = Depends(get_current_user)) -> List[TaskOut]:
    init_db()
    with get_conn() as conn:
        rows = conn.execute("SELECT id, title, points FROM tasks ORDER BY id ASC").fetchall()
    return [TaskOut(**dict(row)) for row in rows]


@app.post("/submit", response_model=SubmissionOut)
def submit(payload: SubmitRequest, user: sqlite3.Row = Depends(get_current_user)) -> SubmissionOut:
    init_db()
    with get_conn() as conn:
        task = conn.execute("SELECT * FROM tasks WHERE id = ?", (payload.task_id,)).fetchone()
        if task is None:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Task not found")
        is_correct = payload.answer.strip().lower() == str(task["answer"]).strip().lower()
        points_awarded = int(task["points"]) if is_correct else 0
        cur = conn.execute("INSERT INTO submissions (user_id, task_id, answer, is_correct, points_awarded) VALUES (?, ?, ?, ?, ?)", (user["id"], payload.task_id, payload.answer, int(is_correct), points_awarded))
        if points_awarded:
            conn.execute("UPDATE users SET points = points + ? WHERE id = ?", (points_awarded, user["id"]))
        submission = conn.execute("SELECT * FROM submissions WHERE id = ?", (cur.lastrowid,)).fetchone()
    return SubmissionOut(**dict(submission))


@app.get("/submissions/{submission_id}", response_model=SubmissionOut)
def get_submission(submission_id: int, user: sqlite3.Row = Depends(get_current_user)) -> SubmissionOut:
    init_db()
    with get_conn() as conn:
        submission = conn.execute("SELECT * FROM submissions WHERE id = ?", (submission_id,)).fetchone()
    if submission is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Submission not found")
    if submission["user_id"] != user["id"] and not user["is_admin"]:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Forbidden")
    return SubmissionOut(**dict(submission))


@app.get("/ranking", response_model=List[RankingRow])
def ranking(_: sqlite3.Row = Depends(get_current_user)) -> List[RankingRow]:
    init_db()
    with get_conn() as conn:
        rows = conn.execute("SELECT username, points FROM users ORDER BY points DESC, username ASC").fetchall()
    return [RankingRow(**dict(row)) for row in rows]


@app.delete("/users/{user_id}")
def delete_user(user_id: int, _: sqlite3.Row = Depends(require_admin)) -> Dict[str, str]:
    init_db()
    if user_id == 1:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Cannot delete admin")
    with get_conn() as conn:
        result = conn.execute("DELETE FROM users WHERE id = ?", (user_id,))
        if result.rowcount == 0:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="User not found")
    return {"message": "deleted"}

