from __future__ import annotations

import base64
import hashlib
import hmac
import json
import os
import sqlite3
import time
from pathlib import Path
from typing import Any, Optional

from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

APP_DB = Path("app.db")
JWT_ALGORITHM = "HS256"
JWT_EXP_SECONDS = 60 * 60 * 24

app = FastAPI(title="Zadania")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"] ,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)
security = HTTPBearer(auto_error=False)


class RegisterRequest(BaseModel):
    username: str = Field(min_length=1, max_length=64)
    password: str = Field(min_length=1, max_length=256)


class LoginRequest(BaseModel):
    username: str = Field(min_length=1, max_length=64)
    password: str = Field(min_length=1, max_length=256)


class SubmitRequest(BaseModel):
    task_id: int
    answer: str = Field(min_length=1, max_length=256)


class TokenResponse(BaseModel):
    token: str


class TaskResponse(BaseModel):
    id: int
    title: str
    points: int


class SubmissionResponse(BaseModel):
    id: int
    user_id: int
    task_id: int
    answer: str
    correct: bool
    points_awarded: int
    created_at: str


class RankingRow(BaseModel):
    username: str
    points: int


class UserRecord:
    def __init__(self, row: sqlite3.Row):
        self.id = row["id"]
        self.username = row["username"]
        self.password_hash = row["password_hash"]
        self.is_admin = bool(row["is_admin"])
        self.points = row["points"]


def get_db() -> sqlite3.Connection:
    conn = sqlite3.connect(APP_DB)
    conn.row_factory = sqlite3.Row
    return conn


def get_jwt_secret() -> str:
    secret = os.environ.get("JWT_SECRET")
    if not secret:
        raise RuntimeError("JWT_SECRET environment variable is required")
    return secret


def hash_password(password: str) -> str:
    salt = b"zadania-salt"
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 120000).hex()


def verify_password(password: str, password_hash: str) -> bool:
    return hmac.compare_digest(hash_password(password), password_hash)


def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def b64url_decode(data: str) -> bytes:
    padding = "=" * (-len(data) % 4)
    return base64.urlsafe_b64decode(data + padding)


def encode_jwt(payload: dict[str, Any], secret: str) -> str:
    header = {"alg": JWT_ALGORITHM, "typ": "JWT"}
    header_b64 = b64url_encode(json.dumps(header, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    signing_input = f"{header_b64}.{payload_b64}".encode("ascii")
    signature = hmac.new(secret.encode("utf-8"), signing_input, hashlib.sha256).digest()
    return f"{header_b64}.{payload_b64}.{b64url_encode(signature)}"


def decode_jwt(token: str, secret: str) -> dict[str, Any]:
    try:
        header_b64, payload_b64, sig_b64 = token.split(".")
        signing_input = f"{header_b64}.{payload_b64}".encode("ascii")
        expected_sig = hmac.new(secret.encode("utf-8"), signing_input, hashlib.sha256).digest()
        if not hmac.compare_digest(expected_sig, b64url_decode(sig_b64)):
            raise ValueError("bad signature")
        payload = json.loads(b64url_decode(payload_b64).decode("utf-8"))
        if payload.get("exp") is None or int(payload["exp"]) < int(time.time()):
            raise ValueError("expired")
        if payload.get("sub") is None:
            raise ValueError("missing sub")
        return payload
    except Exception as exc:
        raise ValueError("invalid token") from exc


def init_db() -> None:
    with get_db() as conn:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                is_admin INTEGER NOT NULL DEFAULT 0,
                points INTEGER NOT NULL DEFAULT 0
            );

            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                answer TEXT NOT NULL,
                points INTEGER NOT NULL
            );

            CREATE TABLE IF NOT EXISTS submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                task_id INTEGER NOT NULL,
                answer TEXT NOT NULL,
                correct INTEGER NOT NULL,
                points_awarded INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                FOREIGN KEY(user_id) REFERENCES users(id),
                FOREIGN KEY(task_id) REFERENCES tasks(id)
            );
            """
        )
        if conn.execute("SELECT id FROM users WHERE username = ?", ("admin",)).fetchone() is None:
            conn.execute(
                "INSERT INTO users (username, password_hash, is_admin, points) VALUES (?, ?, 1, 0)",
                ("admin", hash_password("admin123")),
            )
        if conn.execute("SELECT COUNT(*) AS c FROM tasks").fetchone()["c"] == 0:
            conn.executemany(
                "INSERT INTO tasks (title, answer, points) VALUES (?, ?, ?)",
                [
                    ("Ile to 2 + 2?", "4", 1),
                    ("Stolica Polski?", "Warszawa", 2),
                    ("Rok bitwy pod Grunwaldem?", "1410", 3),
                ],
            )


def create_token(user: UserRecord) -> str:
    payload = {"sub": str(user.id), "username": user.username, "is_admin": user.is_admin, "exp": int(time.time()) + JWT_EXP_SECONDS}
    return encode_jwt(payload, get_jwt_secret())


def get_current_user(credentials: Optional[HTTPAuthorizationCredentials] = Depends(security)) -> UserRecord:
    if credentials is None or credentials.scheme.lower() != "bearer":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing bearer token")
    try:
        payload = decode_jwt(credentials.credentials, get_jwt_secret())
        user_id = int(payload["sub"])
    except (ValueError, KeyError, TypeError):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    with get_db() as conn:
        row = conn.execute("SELECT id, username, password_hash, is_admin, points FROM users WHERE id = ?", (user_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return UserRecord(row)


def require_admin(user: UserRecord = Depends(get_current_user)) -> UserRecord:
    if not user.is_admin:
